namespace CheckoutPricing.Domain;

public static class LoyaltyDiscount
{
    private const int CeilingPoints = 10;

    public static int ForCents(int subtotalCents, LoyaltyTier tier)
    {
        var basePoints = tier switch
        {
            LoyaltyTier.Bronze => 5,
            LoyaltyTier.Silver => 7,
            LoyaltyTier.Gold => 9
        };
        var bonusPoints = subtotalCents switch
        {
            < 5000 => 0,
            < 20000 => 1,
            _ => 3
        };
        var effectivePoints = Math.Min(basePoints + bonusPoints, CeilingPoints);

        return (int)((long)subtotalCents * effectivePoints / 100);
    }
}
E
